#include <iostream>
#include <limits>

int main() {
    std::cout << std::numeric_limits<int>::is_signed << '\n';
    std::cout << (std::numeric_limits<int>::max() >= 32767) << '\n';
    std::cout << (std::numeric_limits<int>::lowest() <= -32767) << '\n';
    std::cout << (std::numeric_limits<unsigned int>::lowest() == 0) << '\n';
    return 0;
}

