#include <iostream>

int main() {
    constexpr double centimetersPerMeter{100.0};
    const long long panelCount{4};
    const long long panelLengthCm{125};
    long long totalLengthCm = panelCount * panelLengthCm;
    // Scaffold: the double factor makes the division floating-point.
    double totalLengthMeters = totalLengthCm / centimetersPerMeter;
    std::cout << "length_cm=" << totalLengthCm << '\n';
    std::cout << "length_m=" << totalLengthMeters << '\n';
    return 0;
}

